import com.google.gson.*;
import com.tangluobo.tomato.module.connect.SqlSplitter;
import java.nio.file.*;
import java.util.*;
/** Compiles and invokes the read-only original SqlSplitter, without JDBC or UI. */
public class SqlScriptGolden {
 public static void main(String[] args)throws Exception {
  Locale.setDefault(Locale.SIMPLIFIED_CHINESE);
  String[] inputs={null,""," \t\r\n; ;","SELECT 1; SELECT 2;","SELECT 'a;''b'; SELECT 2","SELECT \"a;\"\"b\" FROM users;","-- leading ;\nSELECT 1; -- tail","/* a; b */ SELECT 1; SELECT 2","SELECT 1 -- semicolon;\n;SELECT 2","SELECT 'unterminated;","SELECT \"unterminated;","/* unterminated;","SELECT `a;b` FROM users;","DO $$ BEGIN SELECT 1; END $$; SELECT 2;","SELECT 'a\\'; SELECT 2;","SELECT 1--2; SELECT 3","-- comment\rSELECT 1;","SELECT 1 # comment; SELECT 2","SELECT id, name FROM users WHERE enabled=1","SELECT id FROM \"public\".\"users\" u ORDER BY id","SELECT id FROM `app`.`users` u","SELECT id FROM [sales].[orders] o","-- result editable\nSELECT id FROM users AS u WHERE u.id=1","SELECT id FROM users u JOIN roles r ON r.id=u.role_id","SELECT id FROM users u,roles r WHERE r.id=u.role_id","SELECT id FROM users WHERE note='join, later'","SELECT id,(SELECT max(id) FROM audit_log) last_id FROM users","SELECT id FROM users WHERE role_id IN (SELECT id FROM roles)","SELECT id FROM (SELECT id FROM users) u","SELECT id FROM (VALUES (1),(2)) v(id)","SELECT id FROM active_users UNION SELECT id FROM archived_users","SELECT id FROM users WHERE enabled=1 UNION ALL SELECT id FROM archived_users","SELECT id FROM users GROUP BY id EXCEPT SELECT id FROM blocked","SELECT id FROM users ORDER BY id INTERSECT SELECT id FROM other","SELECT id FROM users LIMIT 10 UNION ALL SELECT id FROM archived","WITH c AS (SELECT 1) SELECT * FROM c","SHOW TABLES","DESCRIBE users","DESC users","EXPLAIN SELECT 1","SELECTED nonsense","WITHHOLD anything","/*x*/\u2003SELECT id FROM users","\u00a0SELECT id FROM users","\u0085SELECT id FROM users","\u001cSELECT id FROM users","SELECT * FROM Basic","SELECT * FROM information_schema.tables","SELECT * FROM \"FROM\"","SELECT 'FROM' AS marker FROM users","SELECT `FROM` FROM users","SELECT * FROM users /* JOIN roles */","SELECT * FROM users WHERE note='UNION'","SELECT * FROM users WHERE note='a''UNION''b'","SELECT * FROM users WHERE EXISTS(SELECT * FROM roles UNION SELECT * FROM other)","SELECT * FROM users;DROP TABLE audit;","SELECT 'ß' FROM users","SELECT 'ßßßßß' FROM a","ſELECT id FROM users","SELECT id FROM uſers","SELECT id FROM users WHERE note='İ'","SELECT * FROM 😀表","SELECT * FROM \"a b\"","SELECT * FROM t OFFSET 1 UNION SELECT * FROM x","SELECT * FROM t FOR UPDATE","/*only comment*/","SELECT 1;\u0000 SELECT 2;","SELECT id FROM users joiner WHERE id=1","SELECT id FROM users WHERE union_flag=1"};
  var output=new JsonArray();var gson=new Gson();
  for(var input:inputs){var item=new JsonObject();item.add("input",gson.toJsonTree(input));item.add("statements",gson.toJsonTree(SqlSplitter.split(input)));item.addProperty("select",SqlSplitter.isSelectStatement(input));try{item.add("table",gson.toJsonTree(SqlSplitter.extractTableName(input)));}catch(RuntimeException error){item.addProperty("tableError",error.getClass().getSimpleName());}output.add(item);}
  var path=Path.of(args[0]);Files.createDirectories(path.getParent());Files.writeString(path,new GsonBuilder().setPrettyPrinting().serializeNulls().disableHtmlEscaping().create().toJson(output));
 }
}
